[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('record-phase','summarize-timing','import-usage','cost-report','comparison-report')]
    [string] $Operation,
    [Parameter(Mandatory = $true)]
    [string] $InputPath,
    [string] $StateRoot
)

$ErrorActionPreference = 'Stop'

function Read-Object {
    if (-not (Test-Path -LiteralPath $InputPath -PathType Leaf)) { throw 'Input was not found.' }
    try { $value = ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $InputPath) -AsHashtable -Depth 100 -DateKind String } catch { throw "Input is not valid JSON: $($_.Exception.Message)" }
    if ($value -isnot [System.Collections.IDictionary]) { throw 'Input JSON must be an object.' }
    return $value
}

function Need { param([System.Collections.IDictionary]$Object,[string]$Name); if (-not $Object.Contains($Name) -or $null -eq $Object[$Name] -or [string]::IsNullOrWhiteSpace([string]$Object[$Name])) { throw "$Name is required." }; return [string]$Object[$Name] }
function Get-Stamp { param([string]$Value,[string]$Name); $parsed = [DateTimeOffset]::MinValue; if (-not [DateTimeOffset]::TryParse($Value,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$parsed)) { throw "$Name must be an ISO-8601 timestamp." }; return $parsed }
function Get-Sha256 { param([string]$Text); $sha=[Security.Cryptography.SHA256]::Create(); try { return ([Convert]::ToHexString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))).ToLowerInvariant() } finally { $sha.Dispose() } }
function Get-FileSha256 { param([string]$Path); $sha=[Security.Cryptography.SHA256]::Create();$stream=[IO.File]::OpenRead($Path);try{return ([Convert]::ToHexString($sha.ComputeHash($stream))).ToLowerInvariant()}finally{$stream.Dispose();$sha.Dispose()} }
function Get-Root { if ([string]::IsNullOrWhiteSpace($StateRoot)) { throw 'StateRoot is required.' }; $root=[IO.Path]::GetFullPath($StateRoot); [IO.Directory]::CreateDirectory($root)|Out-Null; return $root }
function Write-AtomicJson { param([string]$Path,[object]$Value);$tmp="$Path.$([Guid]::NewGuid().ToString('N')).tmp";try{[IO.File]::WriteAllText($tmp,($Value|ConvertTo-Json -Depth 100),[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $tmp -Destination $Path -Force}finally{if(Test-Path -LiteralPath $tmp -PathType Leaf){Remove-Item -LiteralPath $tmp -Force}} }
function Read-Registry { param([string]$Root,[string]$RunId);$path=Join-Path $Root 'measurement-registry.json';if(-not(Test-Path -LiteralPath $path -PathType Leaf)){return [ordered]@{schemaVersion=1;runId=$RunId;events=@();updatedAtUtc=$null}};try{$state=ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $path) -AsHashtable -Depth 100 -DateKind String}catch{throw 'Measurement registry is malformed.'};if([int]$state.schemaVersion -ne 1 -or [string]$state.runId -cne $RunId){throw 'Measurement registry schema or run binding is invalid.'};return $state}

function Read-AllEvents {
    param([string]$Root,[string]$RunId)
    $state = Read-Registry $Root $RunId; $items = [System.Collections.Generic.List[object]]::new()
    foreach ($stored in @($state.events)) { [void]$items.Add($stored) }
    $auditPath = Join-Path $Root 'measurement-audit.ndjson'
    if (Test-Path -LiteralPath $auditPath -PathType Leaf) {
        foreach ($line in @(Get-Content -LiteralPath $auditPath)) { if ([string]::IsNullOrWhiteSpace($line)) { continue }; try { $event = ConvertFrom-Json -InputObject $line -AsHashtable -Depth 100 -DateKind String } catch { throw 'Measurement audit contains malformed JSON.' }; if ([string]$event.runId -ceq $RunId) { [void]$items.Add($event) } }
    }
    $unique = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal); $result = [System.Collections.Generic.List[object]]::new()
    foreach ($event in $items) { $id = [string]$event.eventId; if ([string]::IsNullOrWhiteSpace($id) -or -not $unique.Add($id)) { continue }; [void]$result.Add($event) }
    return @($result.ToArray() | Sort-Object { [DateTimeOffset]::Parse([string]$_.atUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind) })
}

function Invoke-RecordPhase {
    param([System.Collections.IDictionary]$InputObject)
    $root=Get-Root;$runId=Need $InputObject 'runId';$kind=Need $InputObject 'eventKind';$at=Get-Stamp (Need $InputObject 'atUtc') 'atUtc'
    $allowed=@('dispatch','result_observed','receipt_accepted','phase_change','wait','repair','publication','pause','resume');if($allowed -notcontains $kind){throw "Unsupported eventKind: $kind"}
    $state=Read-Registry $root $runId;$eventId=if($InputObject.Contains('eventId')){Need $InputObject 'eventId'}else{'evt-'+[Guid]::NewGuid().ToString('N')};$knownIds=@($state.events|ForEach-Object{[string]$_.eventId});$auditPath=Join-Path $root 'measurement-audit.ndjson';if(Test-Path -LiteralPath $auditPath -PathType Leaf){foreach($line in @(Get-Content -LiteralPath $auditPath)){if(-not [string]::IsNullOrWhiteSpace($line)){try{$knownEvent=ConvertFrom-Json -InputObject $line -AsHashtable -Depth 20 -DateKind String}catch{throw 'Measurement audit contains malformed JSON.'};if([string]$knownEvent.runId -ceq $runId){$knownIds+=[string]$knownEvent.eventId}}}};if($knownIds -contains $eventId){throw 'Measurement event IDs are immutable.'}
    $duration=$null;if($InputObject.Contains('workerReportedDurationSeconds') -and $null -ne $InputObject.workerReportedDurationSeconds){$duration=[double]$InputObject.workerReportedDurationSeconds;if($duration -lt 0){throw 'workerReportedDurationSeconds must be nonnegative.'}}
    $event=[ordered]@{schemaVersion=1;eventId=$eventId;runId=$runId;eventKind=$kind;phase=if($InputObject.Contains('phase')){[string]$InputObject.phase}else{$null};atUtc=$InputObject.atUtc;source=if($InputObject.Contains('source')){[string]$InputObject.source}else{'coordinator_observation'};workerReportedDurationSeconds=$duration;actionId=if($InputObject.Contains('actionId')){[string]$InputObject.actionId}else{$null};workerId=if($InputObject.Contains('workerId')){[string]$InputObject.workerId}else{$null};metadata=if($InputObject.Contains('metadata')){$InputObject.metadata}else{@{}}}
    $state.events=@($state.events)+@($event);$state.updatedAtUtc=$InputObject.atUtc; if(@($state.events).Count -gt 1000){$state.events=@($state.events | Select-Object -Last 1000)};Write-AtomicJson (Join-Path $root 'measurement-registry.json') $state
    $auditPath=Join-Path $root 'measurement-audit.ndjson';[IO.File]::AppendAllText($auditPath,(($event|ConvertTo-Json -Depth 100 -Compress)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false))
    $alerts=@();$stallMinutes=if($InputObject.Contains('stallAfterMinutes')){[double]$InputObject.stallAfterMinutes}else{$null};if($null -ne $stallMinutes -and $kind -eq 'wait'){$prior=@(Read-AllEvents $root $runId|Where-Object{$_.eventId -cne $eventId -and $_.eventKind -notin @('wait','pause','resume') -and ((-not $InputObject.Contains('actionId') -and [string]$_.phase -ceq [string]$event.phase) -or ($InputObject.Contains('actionId') -and [string]$_.actionId -ceq [string]$event.actionId))}|Sort-Object {Get-Stamp ([string]$_.atUtc) 'progress.atUtc'});if($prior.Count -gt 0){$gap=($at-(Get-Stamp ([string]$prior[-1].atUtc) 'progress.atUtc')).TotalMinutes;if($gap -gt $stallMinutes){$alerts+=([ordered]@{kind='stalled_phase';gapMinutes=$gap;action='observe_or_escalate';cancelsWorker=$false;changesModel=$false})}}}
    return [ordered]@{event=$event;alerts=$alerts;registryEventCount=@($state.events).Count;auditPath=$auditPath;registryRetainsLast=1000;auditIsComplete=$true}
}

function Invoke-SummarizeTiming {
    param([System.Collections.IDictionary]$InputObject)
    $root=Get-Root;$runId=Need $InputObject 'runId';$events=@(Read-AllEvents $root $runId);$actionId=if($InputObject.Contains('actionId')){Need $InputObject 'actionId'}else{$null};$workerId=if($InputObject.Contains('workerId')){Need $InputObject 'workerId'}else{$null};$matching=@($events|Where-Object{($null -eq $actionId -or [string]$_.actionId -ceq $actionId)-and($null -eq $workerId -or [string]$_.workerId -ceq $workerId)});$dispatches=@($matching|Where-Object eventKind -eq 'dispatch');$observations=@($matching|Where-Object eventKind -eq 'result_observed');$receipts=@($matching|Where-Object eventKind -eq 'receipt_accepted');$correlationKnown=($null -ne $actionId -or ($dispatches.Count -le 1 -and $observations.Count -le 1 -and $receipts.Count -le 1));$dispatch=if($correlationKnown){$dispatches|Select-Object -First 1}else{$null};$observed=if($correlationKnown){$observations|Select-Object -First 1}else{$null};$receipt=if($correlationKnown){$receipts|Select-Object -First 1}else{$null}
    $phaseEvents=@($events|Where-Object eventKind -eq 'phase_change');$intervals=@();for($i=1;$i -lt $phaseEvents.Count;$i++){ $from=$phaseEvents[$i-1];$to=$phaseEvents[$i];$intervals+=[ordered]@{from=[string]$from.phase;to=[string]$to.phase;seconds=([DateTimeOffset]::Parse([string]$to.atUtc)-[DateTimeOffset]::Parse([string]$from.atUtc)).TotalSeconds} };$progress=@($events|Where-Object eventKind -notin @('wait','pause','resume'));$lastProgress=if($progress.Count -gt 0){$progress[-1]}else{$null};$terminal=@($events|Where-Object eventKind -in @('publication','receipt_accepted')|Where-Object{$_.metadata.completion -eq 'complete' -or $_.phase -eq 'complete'}).Count -gt 0
    return [ordered]@{runId=$runId;eventCount=$events.Count;correlationKnown=$correlationKnown;dispatchActionId=if($null -ne $dispatch){$dispatch.actionId}else{$null};dispatchWorkerId=if($null -ne $dispatch){$dispatch.workerId}else{$null};dispatchToObservationSeconds=if($dispatch -and $observed){([DateTimeOffset]::Parse([string]$observed.atUtc)-[DateTimeOffset]::Parse([string]$dispatch.atUtc)).TotalSeconds}else{$null};observationToReceiptSeconds=if($observed -and $receipt){([DateTimeOffset]::Parse([string]$receipt.atUtc)-[DateTimeOffset]::Parse([string]$observed.atUtc)).TotalSeconds}else{$null};wallClockPhaseIntervals=$intervals;lastProgressAtUtc=if($null -ne $lastProgress){([DateTimeOffset]::Parse([string]$lastProgress.atUtc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind)).ToUniversalTime().ToString('o')}else{$null};completionKnown=$terminal;workerReportedDurations=@($events|Where-Object{$null -ne $_.workerReportedDurationSeconds}|ForEach-Object{[ordered]@{eventId=$_.eventId;seconds=$_.workerReportedDurationSeconds}});unknownWorkerDurationCount=@($events|Where-Object{$null -eq $_.workerReportedDurationSeconds}).Count;alerts=@()}
}

function Read-Snapshots { param([System.Collections.IDictionary]$InputObject);if(-not $InputObject.Contains('snapshots') -or $InputObject.snapshots -is [string]){throw 'snapshots must be an array.'};return @($InputObject.snapshots)}
function Get-Counters { param([System.Collections.IDictionary]$Snapshot);if(-not $Snapshot.Contains('counters') -or $Snapshot.counters -isnot [System.Collections.IDictionary]){return $null};$names=@('inputTokens','cachedInputTokens','outputTokens','reasoningTokens');$result=[ordered]@{};foreach($name in $names){if(-not $Snapshot.counters.Contains($name)){return $null};$number=0L;if(-not [long]::TryParse([string]$Snapshot.counters[$name],[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$number)-or $number -lt 0){throw "Counter $name is invalid."};$result[$name]=$number};if($result.cachedInputTokens -gt $result.inputTokens){throw 'cachedInputTokens cannot exceed inputTokens.'};if($result.reasoningTokens -gt $result.outputTokens){throw 'reasoningTokens cannot exceed outputTokens when source counters are inclusive.'};return $result}
function Invoke-ImportUsage {
    param([System.Collections.IDictionary]$InputObject)
    $start=Get-Stamp (Need $InputObject 'startedAtUtc') 'startedAtUtc';$end=Get-Stamp (Need $InputObject 'endedAtUtc') 'endedAtUtc';if($end -le $start){throw 'endedAtUtc must be after startedAtUtc.'};$snapshots=Read-Snapshots $InputObject;$seen=@{};$rows=@();$duplicates=0;$later=0;$boundaryUnknown=0
    $missingStream=@($snapshots|Where-Object{-not $_.Contains('streamId')});$explicitStream=@($snapshots|Where-Object{$_.Contains('streamId')});if($missingStream.Count -gt 0){if($explicitStream.Count -gt 0){throw 'Snapshots must either all provide streamId or use the explicit legacy single-stream adapter.'};$legacyIdentities=@($snapshots|ForEach-Object{"$($_.role)|$($_.model)|$($_.effort)"}|Select-Object -Unique);if($legacyIdentities.Count -ne 1){throw 'Legacy snapshots without streamId are ambiguous across multiple role/model/effort streams.'};foreach($snapshot in $snapshots){$snapshot.streamId='legacy-single-stream'}}
    foreach($snapshot in $snapshots){foreach($name in @('role','model','effort','atUtc','streamId')){Need $snapshot $name|Out-Null};$stamp=Get-Stamp $snapshot.atUtc 'snapshot.atUtc';$counters=Get-Counters $snapshot;$identity=Get-Sha256 ("$($snapshot.streamId)|$($snapshot.atUtc)|"+($counters|ConvertTo-Json -Depth 20 -Compress));if($seen.ContainsKey($identity)){$duplicates++;continue};$seen[$identity]=$true;if($stamp -gt $end){$later++};$rows+=[ordered]@{snapshot=$snapshot;stamp=$stamp;counters=$counters;identity=$identity}}
    $groups=@($rows|Group-Object {"$($_.snapshot.streamId)|$($_.snapshot.role)|$($_.snapshot.model)|$($_.snapshot.effort)"});$roles=@()
    foreach($group in $groups){$ordered=@($group.Group|Sort-Object stamp);$baseline=$null;$previous=$null;$segment=0;$deltas=@();$unknown=$false;$exactStart=$false;$inRange=@($ordered|Where-Object{$_.stamp -ge $start -and $_.stamp -le $end});foreach($row in $ordered){$counter=$row.counters;if($row.stamp -lt $start){if($null -ne $counter){$baseline=$counter};continue};if($row.stamp -gt $end){continue};if($null -eq $counter){$unknown=$true;continue};if($row.stamp -eq $start){$previous=$counter;$exactStart=$true;continue};if($null -eq $previous){$boundaryUnknown++;$unknown=$true;$previous=$counter;continue};$reset=$false;$delta=[ordered]@{};foreach($key in $counter.Keys){if($counter[$key] -lt $previous[$key]){$reset=$true};$delta[$key]=$counter[$key]-$previous[$key]};if($reset){$segment++;$deltas+=[ordered]@{segment=$segment;streamId=[string]$row.snapshot.streamId;atUtc=$row.snapshot.atUtc;delta=$null;reset=$true;attribution='in_run'};$unknown=$true}else{$deltas+=[ordered]@{segment=$segment;streamId=[string]$row.snapshot.streamId;atUtc=$row.snapshot.atUtc;delta=$delta;reset=$false;attribution='in_run'}};$previous=$counter}
        $roles+=[ordered]@{streamId=[string]$group.Group[0].snapshot.streamId;role=$group.Group[0].snapshot.role;model=$group.Group[0].snapshot.model;effort=$group.Group[0].snapshot.effort;segments=$segment+1;deltas=$deltas;inRangeSamples=$inRange.Count;unknown=$unknown -or ($inRange.Count -eq 0);boundaryBaselineAvailable=($exactStart -or $null -ne $baseline);exactStartSample=$exactStart;requestCountsProven=$false}
    }
    return [ordered]@{schemaVersion=1;startedAtUtc=$InputObject.startedAtUtc;endedAtUtc=$InputObject.endedAtUtc;roles=$roles;duplicateSnapshots=$duplicates;postRunSnapshots=$later;postRunDeltasExcluded=$true;boundarySamplesUnknown=$boundaryUnknown;counterResets=@($roles|ForEach-Object{@($_.deltas|Where-Object reset)}|Measure-Object|Select-Object -ExpandProperty Count);missingUsageIsUnknown=$true;requestCountsProven=$false;streamIdAdapter=if($missingStream.Count -gt 0){'legacy-single-stream'}else{'explicit'};source=if($InputObject.Contains('source')){[string]$InputObject.source}else{'explicit_usage_export'}}
}

function Invoke-CostReport {
    param([System.Collections.IDictionary]$InputObject)
    if(-not $InputObject.Contains('usage')){throw 'usage is required.'};$usage=$InputObject.usage;$estimates=@();$actual=if($InputObject.Contains('actualConsumption')){$InputObject.actualConsumption}else{$null};$subscription=if($InputObject.Contains('subscriptionUsage')){$InputObject.subscriptionUsage}else{$null}
    foreach($item in @($usage)){foreach($name in @('role','model','effort')){Need $item $name|Out-Null};$rate=$null;if($InputObject.Contains('rates') -and $InputObject.rates.Contains([string]$item.model)){$rate=$InputObject.rates[[string]$item.model]};$estimate=$null;$unavailable=$null;if($null -eq $rate){$unavailable='missing_rate'}else{$rateFields=@('effectiveAtUtc','source','inputPerMillion','cachedInputPerMillion','outputPerMillion','reasoningIncludedInOutput');$missing=@($rateFields|Where-Object{-not $rate.Contains($_)-or [string]::IsNullOrWhiteSpace([string]$rate[$_])});$rateDate=[DateTimeOffset]::MinValue;if($missing.Count -gt 0-or -not [DateTimeOffset]::TryParse([string]$rate.effectiveAtUtc,[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::RoundtripKind,[ref]$rateDate)){$unavailable='rate_missing_date_source_or_semantics'}elseif(-not $item.Contains('inputTokens')-or -not $item.Contains('cachedInputTokens')-or -not $item.Contains('outputTokens')){$unavailable='usage_counters_incomplete'}else{$input=[double]$item.inputTokens;$cached=[double]$item.cachedInputTokens;$output=[double]$item.outputTokens;if($input -lt 0-or$cached -lt 0-or$output -lt 0-or$cached -gt $input){$unavailable='usage_counters_invalid'}else{$estimate=(($input-$cached)*[double]$rate.inputPerMillion+$cached*[double]$rate.cachedInputPerMillion+$output*[double]$rate.outputPerMillion)/1000000}}};$estimates+=[ordered]@{role=$item.role;model=$item.model;effort=$item.effort;rawUsage=$item;apiEstimateUsd=$estimate;estimateSource=if($null -ne $rate){[string]$rate.source}else{$null};estimateUnavailableReason=$unavailable;reasoningIncludedInOutput=if($null -ne $rate){[bool]$rate.reasoningIncludedInOutput}else{$null}}
    }
    $actualAvailable=$false;$subscriptionAvailable=$false;if($null -ne $actual){if($actual -isnot [System.Collections.IDictionary] -or -not $actual.Contains('source')-or -not $actual.Contains('runId')-or [string]::IsNullOrWhiteSpace([string]$actual.source)-or [string]::IsNullOrWhiteSpace([string]$actual.runId)){throw 'actualConsumption must include source and runId for attribution.'};$actualAvailable=$true};if($null -ne $subscription){if($subscription -isnot [System.Collections.IDictionary] -or -not $subscription.Contains('source')-or -not $subscription.Contains('runId')-or [string]::IsNullOrWhiteSpace([string]$subscription.source)-or [string]::IsNullOrWhiteSpace([string]$subscription.runId)){throw 'subscriptionUsage must include source and runId for attribution.'};$subscriptionAvailable=$true};return [ordered]@{usage=$estimates;actualMonetaryConsumption=$actual;subscriptionConsumption=$subscription;actualCostAvailable=$actualAvailable;subscriptionAttributionAvailable=$subscriptionAvailable;rawTokensAreNotCost=$true;automaticModelChange=$false}
}

function Invoke-Comparison {
    param([System.Collections.IDictionary]$InputObject)
    if(-not $InputObject.Contains('runs') -or @($InputObject.runs).Count -ne 2){throw 'runs must contain exactly two comparison runs.'};$runs=@($InputObject.runs);$same=$true;$reasons=@();foreach($field in @('scopeHash','repositoryRequirementsHash','profilesHash')){if(-not $runs[0].Contains($field)-or-not $runs[1].Contains($field)-or[string]::IsNullOrWhiteSpace([string]$runs[0][$field])-or[string]::IsNullOrWhiteSpace([string]$runs[1][$field])){$same=$false;$reasons+="$field missing"}elseif([string]$runs[0][$field] -cne [string]$runs[1][$field]){$same=$false;$reasons+="$field differs"}};foreach($run in $runs){if(-not $run.Contains('quality')-or[string]::IsNullOrWhiteSpace([string]$run.quality)){$same=$false;$reasons+='quality missing'};$defects=0L;if(-not $run.Contains('acceptedDefects')-or-not [long]::TryParse([string]$run.acceptedDefects,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$defects)-or$defects -lt 0){$same=$false;$reasons+='acceptedDefects invalid'};$seconds=0.0;if(-not $run.Contains('wallClockSeconds')-or-not [double]::TryParse([string]$run.wallClockSeconds,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$seconds)-or$seconds -lt 0){$same=$false;$reasons+='wallClockSeconds invalid'}};return [ordered]@{comparable=$same;nonComparableReasons=$reasons;runs=@($runs|ForEach-Object{[ordered]@{name=$_.name;quality=$_.quality;acceptedDefects=$_.acceptedDefects;wallClockSeconds=$_.wallClockSeconds;usage=$_.usage;coordinationActions=$_.coordinationActions;repairCounts=$_.repairCounts;actualCost=if($_.Contains('actualCost')){$_.actualCost}else{$null};estimatedCost=if($_.Contains('estimatedCost')){$_.estimatedCost}else{$null}}});rawTokenDifference=if($same){[double]$runs[1].totalTokens-[double]$runs[0].totalTokens}else{$null};qualityGate='acceptance_and_quality';rawTokenReductionIsNotAReleaseGate=$true;costUnknownWhenUnattributed=$true;modelSelection='explicit_only'}
}

try{$inputObject=Read-Object;$data=switch($Operation){'record-phase'{Invoke-RecordPhase $inputObject};'summarize-timing'{Invoke-SummarizeTiming $inputObject};'import-usage'{Invoke-ImportUsage $inputObject};'cost-report'{Invoke-CostReport $inputObject};'comparison-report'{Invoke-Comparison $inputObject}};[ordered]@{ok=$true;operation=$Operation;data=$data}|ConvertTo-Json -Depth 100;exit 0}catch{[ordered]@{ok=$false;operation=$Operation;error=[ordered]@{category='workflow_measure';message=$_.Exception.Message}}|ConvertTo-Json -Depth 20;exit 1}
